/**
 * rule_001_regression.test.js
 * Regression test for RULE-001: "A cancelled order must never be shipped."
 *
 * Generated by InvariantOS Test Gap Agent.
 *
 * Verification contract:
 *   - This test MUST FAIL on branch feature/cancel-status-bug
 *     (where the guard reads `order.status !== 'CANCELLED'`).
 *   - This test MUST PASS on branch main
 *     (where the guard reads `order.status === 'PAID'`).
 *
 * Call chain under test:
 *   cancelOrder → updateOrderStatus → shipmentJob → warehouseAPI.createShipment
 */

'use strict';

const { cancelOrder } = require('../../src/orders');
const { shipmentJob } = require('../../src/shipments');
const warehouseApi   = require('../../src/warehouseApi');

jest.mock('../../src/warehouseApi');
jest.mock('../../src/inventory', () => ({
  decrementInventory: jest.fn().mockResolvedValue(undefined),
}));

describe('RULE-001 regression — cancelled order must never be shipped', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    warehouseApi.createShipment.mockResolvedValue({ shipmentId: 'SHIP-REGRESSION', status: 'CREATED' });
  });

  // -------------------------------------------------------------------------
  // PRIMARY REGRESSION TEST — this is the one that catches the seeded bug
  // -------------------------------------------------------------------------
  test('CANCELLED order: shipmentJob must NOT call warehouseApi.createShipment', async () => {
    // Simulate the cancelOrder → updateOrderStatus path
    const originalOrder = { id: 'ORD-CANCEL-REG', status: 'PAID', items: [] };
    const cancelledOrder = cancelOrder(originalOrder);

    expect(cancelledOrder.status).toBe('CANCELLED');

    // Now pass the cancelled order to the shipment job
    const result = await shipmentJob(cancelledOrder);

    // RULE-001: createShipment must NOT have been called
    // On the buggy branch (status !== 'CANCELLED'), this assertion FAILS because
    // the condition `'CANCELLED' !== 'CANCELLED'` is false, so CANCELLED orders
    // skip the guard and proceed to createShipment — violating RULE-001.
    expect(warehouseApi.createShipment).not.toHaveBeenCalled();
    expect(result).toBeNull();
  });

  // -------------------------------------------------------------------------
  // COMPLEMENTARY TEST — verify PAID orders still get shipped (no over-blocking)
  // -------------------------------------------------------------------------
  test('PAID order: shipmentJob SHOULD call warehouseApi.createShipment', async () => {
    const paidOrder = { id: 'ORD-PAID-REG', status: 'PAID', items: [] };
    await shipmentJob(paidOrder);
    expect(warehouseApi.createShipment).toHaveBeenCalledTimes(1);
  });

  // -------------------------------------------------------------------------
  // CALL CHAIN INTEGRATION — full path: cancelOrder → shipmentJob
  // -------------------------------------------------------------------------
  test('Full call chain: cancelOrder result passed to shipmentJob never triggers createShipment', async () => {
    const statuses = ['PAID', 'PENDING'];

    for (const initialStatus of statuses) {
      jest.clearAllMocks();
      // Some statuses can't be cancelled directly; only test valid transitions
      if (initialStatus === 'PAID' || initialStatus === 'PENDING') {
        const order = { id: `ORD-CHAIN-${initialStatus}`, status: initialStatus, items: [] };
        const cancelled = cancelOrder(order);
        await shipmentJob(cancelled);
        expect(warehouseApi.createShipment).not.toHaveBeenCalled();
      }
    }
  });

  // -------------------------------------------------------------------------
  // EDGE CASES — other non-PAID statuses should also be blocked
  // -------------------------------------------------------------------------
  test('REFUNDED order: shipmentJob must NOT call warehouseApi.createShipment', async () => {
    const order = { id: 'ORD-REFUNDED-REG', status: 'REFUNDED', items: [] };
    const result = await shipmentJob(order);
    expect(warehouseApi.createShipment).not.toHaveBeenCalled();
    expect(result).toBeNull();
  });

  test('PENDING order: shipmentJob must NOT call warehouseApi.createShipment', async () => {
    const order = { id: 'ORD-PENDING-REG', status: 'PENDING', items: [] };
    const result = await shipmentJob(order);
    expect(warehouseApi.createShipment).not.toHaveBeenCalled();
    expect(result).toBeNull();
  });

  test('DELIVERED order: shipmentJob must NOT call warehouseApi.createShipment', async () => {
    const order = { id: 'ORD-DELIVERED-REG', status: 'DELIVERED', items: [] };
    const result = await shipmentJob(order);
    expect(warehouseApi.createShipment).not.toHaveBeenCalled();
    expect(result).toBeNull();
  });
});
